def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances: dict[str, int] = {}
    frozen: set[str] = set()
    # Each entry is a closure that undoes a successful operation.
    undo_stack: list = []
    rejected: list[int] = []

    def parse_amount(tok: str) -> int | None:
        if tok == "" or not tok.isdigit():
            return None
        return int(tok)

    for i, op in enumerate(ops):
        parts = op.split(" ")
        verb = parts[0] if parts else ""
        ok = False
        undo_fn = None

        if verb == "open" and len(parts) == 3:
            a, n = parts[1], parse_amount(parts[2])
            if n is not None and n >= 0 and a not in balances:
                balances[a] = n
                undo_fn = lambda a=a: (balances.pop(a, None), frozen.discard(a))
                ok = True

        elif verb == "deposit" and len(parts) == 3:
            a, n = parts[1], parse_amount(parts[2])
            if n is not None and n > 0 and a in balances:
                balances[a] += n
                undo_fn = lambda a=a, n=n: balances.__setitem__(a, balances[a] - n)
                ok = True

        elif verb == "withdraw" and len(parts) == 3:
            a, n = parts[1], parse_amount(parts[2])
            if n is not None and n > 0 and a in balances and a not in frozen and balances[a] >= n:
                balances[a] -= n
                undo_fn = lambda a=a, n=n: balances.__setitem__(a, balances[a] + n)
                ok = True

        elif verb == "transfer" and len(parts) == 4:
            a, b, n = parts[1], parts[2], parse_amount(parts[3])
            if (n is not None and n > 0 and a != b and a in balances and b in balances
                    and a not in frozen and balances[a] >= n):
                balances[a] -= n
                balances[b] += n
                undo_fn = lambda a=a, b=b, n=n: (
                    balances.__setitem__(a, balances[a] + n),
                    balances.__setitem__(b, balances[b] - n),
                )
                ok = True

        elif verb == "freeze" and len(parts) == 2:
            a = parts[1]
            if a in balances and a not in frozen:
                frozen.add(a)
                undo_fn = lambda a=a: frozen.discard(a)
                ok = True

        elif verb == "unfreeze" and len(parts) == 2:
            a = parts[1]
            if a in balances and a in frozen:
                frozen.discard(a)
                undo_fn = lambda a=a: frozen.add(a)
                ok = True

        elif verb == "undo" and len(parts) == 1:
            if undo_stack:
                undo_stack.pop()()
                ok = True

        if ok:
            if verb != "undo" and undo_fn is not None:
                undo_stack.append(undo_fn)
        else:
            rejected.append(i)

    return balances, rejected
